<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>WastedToken Mint — Physical Proof of Participation</title>
<style>
  :root{
    --ink:#07100f;
    --panel:#0c1917;
    --line:rgba(190,242,218,.16);
    --mint:#b7f7d2;
    --acid:#d9ff65;
    --muted:#91aaa2;
    --paper:#e6eee7;
  }
  *{box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    margin:0;background:var(--ink);color:var(--paper);
    font-family:Arial,Helvetica,sans-serif;letter-spacing:.02em;
  }
  .topline{
    height:5px;background:linear-gradient(90deg,#b06a32,#e3e8e4,#e8b72b,#202425,#b7f7d2);
  }
  nav{
    display:flex;align-items:center;justify-content:space-between;
    max-width:1240px;margin:auto;padding:22px 28px;border-bottom:1px solid var(--line);
  }
  .brand{font-weight:900;letter-spacing:.13em;font-size:14px;color:var(--mint)}
  .brand b{color:var(--acid)}
  nav a{font-size:11px;text-transform:uppercase;color:var(--muted);text-decoration:none;letter-spacing:.15em}
  .hero{
    max-width:1240px;margin:auto;padding:35px 28px 68px;
    display:grid;grid-template-columns:minmax(260px,.84fr) minmax(420px,1.3fr);gap:34px;align-items:center;
  }
  .kicker{color:var(--acid);font-size:11px;font-weight:bold;letter-spacing:.22em;text-transform:uppercase}
  h1{
    margin:14px 0 20px;font-size:clamp(46px,7vw,94px);line-height:.88;
    letter-spacing:-.075em;text-transform:uppercase;max-width:620px;
  }
  h1 span{color:var(--mint)}
  .hero p{color:#a8bbb4;line-height:1.65;max-width:455px;font-size:15px}
  .facts{display:flex;gap:25px;margin-top:27px}
  .facts div{border-left:2px solid var(--acid);padding-left:11px}
  .facts strong{display:block;font-size:17px;color:white}
  .facts small{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.12em}
  .coin-stage{
    background:#091210;border:1px solid rgba(183,247,210,.15);
    min-height:500px;position:relative;overflow:hidden;
  }
  .coin-stage:before{
    content:"";position:absolute;inset:12px;border:1px solid rgba(183,247,210,.06);pointer-events:none;
  }
  #coin-hero{display:block;width:100%;height:500px;position:relative}
  .caption{
    position:absolute;bottom:18px;left:20px;font-size:10px;letter-spacing:.16em;color:#6c887f;text-transform:uppercase;
  }
  section{max-width:1240px;margin:auto;padding:82px 28px}
  .about{border-top:1px solid var(--line);display:grid;grid-template-columns:.7fr 1.3fr;gap:55px}
  .section-label{font-size:11px;letter-spacing:.2em;color:var(--acid);font-weight:bold;text-transform:uppercase}
  h2{margin:10px 0;font-size:clamp(34px,4vw,58px);line-height:.96;letter-spacing:-.06em;text-transform:uppercase}
  .about p{font-size:18px;line-height:1.65;color:#b8c8c1;max-width:670px;margin:0}
  .about p + p{margin-top:18px;font-size:14px;color:#8fa59d}
  .collection{border-top:1px solid var(--line);padding-top:68px}
  .collection-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:30px}
  .collection-head p{color:var(--muted);font-size:13px;max-width:350px;line-height:1.5}
  .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
  .edition{
    min-height:420px;background:linear-gradient(155deg,#10201d,#09110f);
    border:1px solid var(--line);padding:15px;display:flex;flex-direction:column;position:relative;
  }
  .edition:hover{border-color:rgba(217,255,101,.48);transform:translateY(-3px)}
  .edition-canvas{display:block;width:100%;height:225px;background:#091210}
  .edition h3{font-size:23px;letter-spacing:-.05em;text-transform:uppercase;margin:19px 0 6px}
  .edition p{font-size:11px;line-height:1.5;color:var(--muted);margin:0 0 16px;text-transform:uppercase;letter-spacing:.08em}
  .tag{font-size:10px;letter-spacing:.14em;color:var(--acid);font-weight:bold;margin-top:auto;text-transform:uppercase}
  .tag.sold{color:#f18e76}.tag.next{color:#b7c8ff}
  button.buy{
    border:1px solid var(--acid);background:var(--acid);color:#0a130f;
    cursor:pointer;padding:12px 10px;font-weight:bold;text-transform:uppercase;
    letter-spacing:.13em;font-size:10px;margin-top:13px;
  }
  button.buy:hover{background:white;border-color:white}
  footer{border-top:1px solid var(--line);padding:27px 28px;max-width:1240px;margin:auto;color:#637c73;font-size:10px;letter-spacing:.13em;text-transform:uppercase;display:flex;justify-content:space-between}
  @media(max-width:850px){
    .hero{grid-template-columns:1fr}.coin-stage{min-height:390px}#coin-hero{height:390px}
    .about{grid-template-columns:1fr;gap:10px}.grid{grid-template-columns:repeat(2,1fr)}
  }
  @media(max-width:480px){.grid{grid-template-columns:1fr}.hero{padding-inline:16px}section{padding-inline:16px}nav{padding-inline:16px}}
</style>
</head>
<body>
<div class="topline"></div>
<nav>
  <div class="brand">WASTED<b>TOKEN</b> MINT</div>
  <a href="#collection">The 2025 Run ↓</a>
</nav>

<main>
  <section class="hero">
    <div>
      <div class="kicker">Physical proof of participation</div>
      <h1>Spend<br>your <span>legend.</span></h1>
      <p>We turn glorious bad decisions, heroic side quests, and internet folklore into weighty, numbered metal. Every WastedToken is struck to be carried, traded, and explained badly at parties.</p>
      <div class="facts">
        <div><strong>39 mm</strong><small>Collector diameter</small></div>
        <div><strong>3.5 mm</strong><small>Reeded edge</small></div>
        <div><strong>∞ lore</strong><small>On-chain spirit</small></div>
      </div>
    </div>
    <div class="coin-stage">
      <canvas id="coin-hero" aria-label="Animated rotating WastedToken challenge coin"></canvas>
      <div class="caption">Rotate / flip / receive no financial advice</div>
    </div>
  </section>

  <section class="about">
    <div>
      <div class="section-label">The mint</div>
      <h2>Heavy is the meme.</h2>
    </div>
    <div>
      <p>WastedToken Mint is a small, stubborn mint for people who understand that the best digital souvenirs deserve an analog twin. We make challenge coins with the finish, heft, and unnecessarily elaborate edge treatment of a thing worth keeping.</p>
      <p>Each release is a finite physical run. No utility roadmap. No yield. Just a beautifully made token for the moments you absolutely should have logged off.</p>
    </div>
  </section>

  <section class="collection" id="collection">
    <div class="collection-head">
      <div>
        <div class="section-label">Series 01 / The participation trophy</div>
        <h2>Choose your damage.</h2>
      </div>
      <p>Four finishes. One denomination. All struck with a reeded edge and enough reflective drama to distract from your wallet history.</p>
    </div>
    <div class="grid">
      <div class="edition" data-edition="bronze" data-state="available">
        <canvas class="edition-canvas" aria-label="Bronze WastedToken coin"></canvas>
        <h3>Bronze</h3>
        <p>Raw, warm, and proudly overcommitted.</p>
        <div class="tag">Available · 1,000 tokens</div>
        <button class="buy" type="button">Add to cart</button>
      </div>
      <div class="edition" data-edition="silver" data-state="available">
        <canvas class="edition-canvas" aria-label="Silver WastedToken coin"></canvas>
        <h3>Silver</h3>
        <p>For the cleanest possible bad idea.</p>
        <div class="tag">Available · 500 tokens</div>
        <button class="buy" type="button">Add to cart</button>
      </div>
      <div class="edition" data-edition="gold" data-state="sold-out">
        <canvas class="edition-canvas" aria-label="Gold WastedToken coin"></canvas>
        <h3>Gold</h3>
        <p>The gilded receipt for peak nonsense.</p>
        <div class="tag sold">SOLD OUT · 100 tokens</div>
      </div>
      <div class="edition" data-edition="black" data-state="coming-soon">
        <canvas class="edition-canvas" aria-label="Black obsidian WastedToken coin"></canvas>
        <h3>Black / Obsidian</h3>
        <p>Light-swallowing finish. Sharp intentions.</p>
        <div class="tag next">Minting Winter 2025</div>
      </div>
    </div>
  </section>
</main>
<footer><span>© WastedToken Mint</span><span>Strike first. Ask about utility never.</span></footer>

<script>
(() => {
  const palettes = {
    bronze:{base:"#a85d2b", dark:"#402012", rim:"#d99a54", bright:"#ffe2a3", ink:"#3a1d10"},
    silver:{base:"#9eaaa8", dark:"#35403f", rim:"#e8f5ef", bright:"#ffffff", ink:"#32403d"},
    gold:{base:"#c89419", dark:"#51380b", rim:"#ffd95e", bright:"#fff0a1", ink:"#5c3d08"},
    black:{base:"#20282b", dark:"#050708", rim:"#69777d", bright:"#d4eef0", ink:"#06090b"}
  };

  function fit(canvas){
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = Math.max(1, Math.round(canvas.clientWidth*dpr));
    const h = Math.max(1, Math.round(canvas.clientHeight*dpr));
    if(canvas.width !== w || canvas.height !== h){ canvas.width=w; canvas.height=h; }
    return {w,h};
  }
  function hexmix(a,b,f){
    const ah=a.replace("#",""), bh=b.replace("#","");
    const ar=parseInt(ah.slice(0,2),16),ag=parseInt(ah.slice(2,4),16),ab=parseInt(ah.slice(4,6),16);
    const br=parseInt(bh.slice(0,2),16),bg=parseInt(bh.slice(2,4),16),bb=parseInt(bh.slice(4,6),16);
    return `rgb(${Math.round(ar+(br-ar)*f)},${Math.round(ag+(bg-ag)*f)},${Math.round(ab+(bb-ab)*f)})`;
  }
  function pathCircle(ctx, project, z, r=1, steps=110){
    ctx.beginPath();
    for(let i=0;i<=steps;i++){
      const a=i/steps*Math.PI*2, p=project(Math.cos(a)*r,Math.sin(a)*r,z);
      i ? ctx.lineTo(p.x,p.y) : ctx.moveTo(p.x,p.y);
    }
    ctx.closePath();
  }

  function drawCoin(canvas, time, finish="bronze", miniature=false){
    const {w,h}=fit(canvas), ctx=canvas.getContext("2d");
    const pal=palettes[finish];
    ctx.clearRect(0,0,w,h);
    ctx.fillStyle="#091210"; ctx.fillRect(0,0,w,h);

    const cx=w*.5, cy=h*.49;
    const scale=Math.min(w,h)*(miniature?.315:.355);
    const depth=.15;
    const ay=time*Math.PI*2;
    const ax=.48*Math.sin(time*Math.PI*2)+.08;
    const sy=Math.sin(ay), cyy=Math.cos(ay), sx=Math.sin(ax), cxx=Math.cos(ax);
    const project=(x,y,z)=>({
      x:cx+scale*(cyy*x+sy*z),
      y:cy-scale*(cxx*y+sx*sy*x-sx*cyy*z)
    });
    const normalZ=cxx*cyy;
    const nearSide=normalZ>=0?1:-1, farSide=-nearSide;

    function facePath(side){ pathCircle(ctx,project,side*depth); }
    function fillFace(side, far){
      facePath(side);
      ctx.save();ctx.clip();
      const hp=project(.38*Math.cos(ay*.72),-.24+Math.sin(ay*.63)*.14,side*depth);
      const rg=ctx.createRadialGradient(hp.x,hp.y,2,hp.x,hp.y,scale*1.08);
      rg.addColorStop(0, pal.bright);
      rg.addColorStop(.08, hexmix(pal.bright,pal.base,.25));
      rg.addColorStop(.28,pal.base);
      rg.addColorStop(.72,hexmix(pal.base,pal.dark,.58));
      rg.addColorStop(1,pal.dark);
      ctx.fillStyle=rg;ctx.fillRect(0,0,w,h);
      const sheen=ctx.createLinearGradient(cx-scale,cy-scale,cx+scale,cy+scale*.15);
      sheen.addColorStop(0,"rgba(255,255,255,0)");
      sheen.addColorStop(.43,"rgba(255,255,255,.05)");
      sheen.addColorStop(.52,far?"rgba(255,255,255,.08)":"rgba(255,255,255,.38)");
      sheen.addColorStop(.61,"rgba(255,255,255,.03)");
      sheen.addColorStop(1,"rgba(0,0,0,.18)");
      ctx.fillStyle=sheen;ctx.fillRect(0,0,w,h);
      ctx.restore();
    }
    fillFace(farSide,true);

    // Cylindrical wall and deterministic individual reeds.
    const seg=108;
    for(let i=0;i<seg;i++){
      const a=i/seg*Math.PI*2, b=(i+1)/seg*Math.PI*2;
      const p1=project(Math.cos(a),Math.sin(a),-depth), p2=project(Math.cos(b),Math.sin(b),-depth);
      const p3=project(Math.cos(b),Math.sin(b),depth), p4=project(Math.cos(a),Math.sin(a),depth);
      const tone=.2+.8*Math.max(0,Math.cos(a-ay-.65))*(i%2?.78:1);
      ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.lineTo(p3.x,p3.y);ctx.lineTo(p4.x,p4.y);ctx.closePath();
      ctx.fillStyle=hexmix(pal.dark,pal.rim,Math.min(.95,tone));
      ctx.fill();
      if(i%2===0){
        ctx.strokeStyle="rgba(0,0,0,.38)";ctx.lineWidth=Math.max(1,scale*.009);
        ctx.beginPath();ctx.moveTo(p2.x,p2.y);ctx.lineTo(p3.x,p3.y);ctx.stroke();
      }
    }
    fillFace(nearSide,false);

    // Planar embossed artwork; the back's x axis is reversed to be readable.
    const center=project(0,0,nearSide*depth+.002);
    const bx={x:scale*cyy*(nearSide===-1?-1:1), y:-scale*sx*sy*(nearSide===-1?-1:1)};
    const by={x:0,y:-scale*cxx};
    ctx.save();
    ctx.transform(bx.x,bx.y,by.x,by.y,center.x,center.y);
    const lw=.025;
    function relief(draw){
      ctx.save();ctx.translate(.018,-.018);ctx.strokeStyle="rgba(20,12,5,.65)";ctx.fillStyle="rgba(20,12,5,.56)";draw();ctx.restore();
      ctx.save();ctx.translate(-.012,.012);ctx.strokeStyle=pal.bright;ctx.fillStyle=pal.bright;draw();ctx.restore();
    }
    relief(()=>{
      ctx.lineWidth=lw;ctx.beginPath();ctx.arc(0,0,.84,0,Math.PI*2);ctx.stroke();
      ctx.lineWidth=.012;ctx.beginPath();ctx.arc(0,0,.71,0,Math.PI*2);ctx.stroke();
    });
    if(nearSide===1){
      relief(()=>{
        ctx.lineWidth=.055;ctx.lineJoin="round";ctx.beginPath();
        ctx.moveTo(-.46,-.27);ctx.lineTo(-.22,.34);ctx.lineTo(0,-.12);ctx.lineTo(.22,.34);ctx.lineTo(.46,-.27);
        ctx.stroke();
        ctx.lineWidth=.019;ctx.beginPath();ctx.moveTo(-.51,.43);ctx.lineTo(.51,.43);ctx.stroke();
      });
      ctx.fillStyle=pal.ink;ctx.font="bold .115px Arial";ctx.textAlign="center";
      ctx.fillText("WASTEDTOKEN",0,-.55);ctx.font="bold .075px Arial";ctx.fillText("MINT • EST. ALWAYS",0,.62);
      for(let i=0;i<10;i++){const a=Math.PI*.18+i*Math.PI*.064;ctx.beginPath();ctx.arc(Math.cos(a)*.58,Math.sin(a)*.58,.022,0,7);ctx.fill();}
    } else {
      relief(()=>{
        ctx.lineWidth=.043;ctx.beginPath();ctx.arc(0,-.05,.38,0,Math.PI*2);ctx.stroke();
      });
      ctx.fillStyle=pal.ink;ctx.textAlign="center";ctx.font="bold .13px Arial";ctx.fillText("10,000",0,-.08);
      ctx.font="bold .075px Arial";ctx.fillText("TOKENS",0,.13);
      ctx.font="bold .065px Arial";ctx.fillText("SPEND RESPONSIBLY*",0,.58);
      ctx.font="bold .055px Arial";ctx.fillText("*OR DON'T",0,-.57);
    }
    ctx.restore();

    // Near rim catches one final moving line of light.
    facePath(nearSide);
    ctx.strokeStyle=hexmix(pal.rim,pal.bright,.5);ctx.lineWidth=Math.max(1,scale*.019);ctx.stroke();
  }

  const hero=document.getElementById("coin-hero");
  let current=0, running=true, raf=0, started=performance.now();
  function renderHero(){drawCoin(hero,current,"bronze",false)}
  function tick(now){
    if(!running)return;
    current=((now-started)/8500)%1;
    renderHero();
    raf=requestAnimationFrame(tick);
  }
  window.demo={
    canvas:hero,
    setTime(t){ current=Math.max(0,Math.min(1,Number(t)||0)); renderHero(); },
    pause(){ running=false; cancelAnimationFrame(raf); }
  };
  renderHero();
  raf=requestAnimationFrame(tick);

  document.querySelectorAll(".edition").forEach((tile,i)=>{
    const finish=tile.dataset.edition;
    drawCoin(tile.querySelector("canvas"), .13+i*.19, finish,true);
  });
  window.addEventListener("resize",()=>{
    renderHero();
    document.querySelectorAll(".edition").forEach((tile,i)=>drawCoin(tile.querySelector("canvas"),.13+i*.19,tile.dataset.edition,true));
  });
  document.querySelectorAll("button.buy").forEach(btn=>btn.addEventListener("click",()=>{
    btn.textContent="Added to stash ✓";btn.style.background="#b7f7d2";btn.disabled=true;
  }));
})();
</script>
</body>
</html>
